/* Unified directory; source records and saved plans remain shared with existing pages. */
const catalog=document.querySelector('#catalog');
catalog.innerHTML=`<header class="catalog-heading"><h1>TOKEN 田野</h1><p>汇集 AI 项目的 Token 羊毛与 Agent Skill，找到适合自己的工具与额度。</p></header><div class="catalog-toolbar" role="search" aria-label="搜索与筛选目录"><div class="catalog-search"><span aria-hidden="true">⌕</span><input id="catalog-query" type="search" placeholder="搜索羊毛、Skill、平台或关键词…" aria-label="搜索目录"></div><div class="catalog-controls"><label>类型 <select id="catalog-type"><option value="全部">全部类型</option><option value="羊毛">Token 羊毛</option><option value="Skill">Agent Skill</option></select></label><label>分类 <select id="catalog-category"><option value="全部">全部分类</option></select></label><label>排序 <select id="catalog-sort"><option value="default">默认排序</option><option value="name">名称排序</option></select></label></div><div class="catalog-tabs"><div><button data-catalog-tab="全部" class="active">全部 <span id="catalog-all-count"></span></button><button data-catalog-tab="羊毛">Token 羊毛 <span id="catalog-benefit-count"></span></button><button data-catalog-tab="Skill">Skill / 资源 <span id="catalog-skill-count"></span></button></div><span id="catalog-count"></span></div><div class="catalog-table-head"><span>名称 / 简介</span><span>类型</span><span>核心标签 / 额度</span><span>来源 / Star</span><span>操作</span></div></div><div id="catalog-results"></div><div class="catalog-pagination"><span id="catalog-page-info"></span><div><button id="catalog-prev">上一页</button><button id="catalog-next">下一页</button></div></div>`;
const catalogData=[...items.map(x=>({kind:'羊毛',name:x.name,desc:x.desc,category:x.type,extra:quotas[x.id]||x.cycle,source:x.name.split(' ')[0],item:x})),...skillItems.map(x=>({kind:'Skill',name:x.name,desc:x.desc,category:x.category,extra:x.category,source:x.owner||x.source,item:x}))];
let catalogPage=1;const catalogSize=20,catType=document.querySelector('#catalog-type'),catCategory=document.querySelector('#catalog-category'),catQuery=document.querySelector('#catalog-query'),catSort=document.querySelector('#catalog-sort');
const catalogEscape=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function catalogCategories(){const current=catCategory.value,values=[...new Set(catalogData.filter(x=>catType.value==='全部'||x.kind===catType.value).map(x=>x.category))];catCategory.innerHTML='<option value="全部">全部分类</option>'+values.map(v=>`<option value="${catalogEscape(v)}">${catalogEscape(v)}</option>`).join('');if(values.includes(current))catCategory.value=current}
function renderCatalog(){const query=catQuery.value.trim().toLowerCase(),type=catType.value,category=catCategory.value;let rows=catalogData.filter(x=>(type==='全部'||x.kind===type)&&(category==='全部'||x.category===category)&&[x.name,x.desc,x.source,x.extra,...(x.kind==='Skill'?x.item.tags||[]:benefitPurposeTags[x.item.id]||[])].join(' ').toLowerCase().includes(query));if(catSort.value==='name')rows.sort((a,b)=>a.name.localeCompare(b.name));const pages=Math.max(1,Math.ceil(rows.length/catalogSize));catalogPage=Math.min(catalogPage,pages);document.querySelector('#catalog-count').textContent=`共 ${rows.length} 项`;document.querySelector('#catalog-all-count').textContent=catalogData.length;document.querySelector('#catalog-benefit-count').textContent=items.length;document.querySelector('#catalog-skill-count').textContent=skillItems.length;document.querySelector('#catalog-page-info').textContent=`第 ${catalogPage} / ${pages} 页 · 每页 ${catalogSize} 项`;document.querySelector('#catalog-prev').disabled=catalogPage===1;document.querySelector('#catalog-next').disabled=catalogPage===pages;document.querySelectorAll('[data-catalog-tab]').forEach(b=>b.classList.toggle('active',b.dataset.catalogTab===type));
document.querySelector('#catalog-results').innerHTML=rows.slice((catalogPage-1)*catalogSize,catalogPage*catalogSize).map(x=>{const i=x.item,isSkill=x.kind==='Skill',idx=isSkill?skillItems.indexOf(i):items.indexOf(i),saved=isSkill?getSavedSkills().includes(i.url):getPlan().includes(i.id),icon=isSkill?catalogEscape(skillSymbols[i.name]||skillMeta[i.mark]?.icon||i.mark):icons[i.id]?`<img src="icons/${icons[i.id]}" alt="">`:catalogEscape(i.icon);return `<article class="catalog-row"><div class="catalog-name"><span class="catalog-icon">${icon}</span><div><strong>${catalogEscape(x.name)}</strong><p>${catalogEscape(x.desc)}</p></div></div><span class="catalog-badge ${isSkill?'is-skill':''}">${isSkill?'Agent Skill':'Token 羊毛'}</span><span class="catalog-extra">${(isSkill?i.tags||[x.category]:benefitPurposeTags[i.id]||[x.category]).map(t=>`<span class="catalog-tag">${catalogEscape(t)}</span>`).join('')}${!isSkill?` <span class="catalog-tag">${catalogEscape(i.cycle)}</span><small>${catalogEscape(x.extra)}</small>`:""}</span><span class="catalog-source">${catalogEscape(x.source)}${isSkill?`<small title="GitHub 仓库 Star 快照：2026-11-14">${catalogEscape(skillStarText(i))}</small>`:""}</span><div class="catalog-actions"><button data-catalog-save="${idx}" data-kind="${x.kind}" aria-label="${saved?'从计划移除':'加入计划'}：${catalogEscape(x.name)}">${saved?'已加入':'加入计划'}</button><button data-catalog-detail="${idx}" data-kind="${x.kind}">详情</button></div></article>`}).join('')||'<p class="catalog-empty">没有找到匹配项目，试试其他关键词或分类。</p>';document.querySelectorAll('[data-catalog-save]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.catalogSave);b.dataset.kind==='Skill'?toggleSkill(skillItems[i].url):toggle(items[i].id);renderCatalog()});document.querySelectorAll('[data-catalog-detail]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.catalogDetail),skill=b.dataset.kind==='Skill',input=document.querySelector(skill?'#skill-search':'#search');location.hash=skill?'skills':'benefits';input.value=skill?skillItems[i].name:items[i].name;input.dispatchEvent(new Event('input',{bubbles:true}))})}
catalogCategories();renderCatalog();catType.onchange=()=>{catalogPage=1;catalogCategories();renderCatalog()};catCategory.onchange=catSort.onchange=()=>{catalogPage=1;renderCatalog()};catQuery.oninput=()=>{catalogPage=1;renderCatalog()};document.querySelectorAll('[data-catalog-tab]').forEach(b=>b.onclick=()=>{catType.value=b.dataset.catalogTab;catalogPage=1;catalogCategories();renderCatalog()});document.querySelector('#catalog-prev').onclick=()=>{catalogPage--;renderCatalog()};document.querySelector('#catalog-next').onclick=()=>{catalogPage++;renderCatalog()};window.addEventListener('hashchange',()=>{if(location.hash==='#catalog')renderCatalog()});

// Keep the search surface below the mobile navigation, whose height can wrap.
const catalogToolbar=document.querySelector('.catalog-toolbar');
const catalogSidebar=document.querySelector('.sidebar');
function updateCatalogStickyOffset(){
 const top=window.matchMedia('(max-width:800px)').matches?catalogSidebar.getBoundingClientRect().height:0;
 catalogToolbar.style.setProperty('--catalog-sticky-offset',`${Math.ceil(top)}px`);
}
new ResizeObserver(updateCatalogStickyOffset).observe(catalogSidebar);
window.addEventListener('resize',updateCatalogStickyOffset);
updateCatalogStickyOffset();
document.querySelector('#catalog-count').setAttribute('aria-live','polite');
